namespace rubinius {
  namespace locks {
    // Adapted from: Anthony Williams. “C++ Concurrency In Action.”

    class spinlock_mutex {
      std::atomic_flag flag;
    public:
      spinlock_mutex()
        : flag()
      {
        reset();
      }

      void reset() {
        flag.clear();
      }

      void lock() {
        while(flag.test_and_set(std::memory_order_seq_cst)) {
          ; // spin
        }
      }

      bool try_lock() {
        return !flag.test_and_set(std::memory_order_seq_cst);
      }

      void unlock() {
        flag.clear(std::memory_order_seq_cst);
        std::atomic_thread_fence(std::memory_order_seq_cst);
      }
    };
  }
}

enum logger_level {
      eFatal  = 1,
      eError  = 2,
      eWarn   = 3,
      eInfo   = 4,
      eDebug  = 5
    };

class Logger {
      rubinius::locks::spinlock_mutex lock_;

#define LOGGER_TIME_SIZE    16

      char formatted_time_[LOGGER_TIME_SIZE];

    public:
      Logger()
        : lock_()
      { }

      virtual ~Logger() { }

      virtual void write(const char* message, int size) = 0;
      virtual void fatal(const char* message, int size) = 0;
      virtual void error(const char* message, int size) = 0;
      virtual void warn(const char* message, int size) = 0;
      virtual void info(const char* message, int size) = 0;
      virtual void debug(const char* message, int size) = 0;

      char* timestamp();

      rubinius::locks::spinlock_mutex& spinlock() {
        return lock_;
      }

      void lock() {
        lock_.lock();
      }

      bool try_lock() {
        return lock_.try_lock();
      }

      void unlock() {
        lock_.unlock();
      }
    };

