// Construct a new spinlock_mutex; default state is unlocked.
rubinius::locks::spinlock_mutex* mutex = new rubinius::locks::spinlock_mutex();
// Track lock ownership state for correctness across stubs.
FUZZ_SET_ATTR_INT(mutex, "held", 0);
// Validation: After construction, the lock should be unlocked.
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(mutex, "held") == 0, "spinlock must start unlocked");
// Output: mutex persists in the pool for subsequent operations.

// Ensure no one holds the lock before reset; otherwise it breaks mutual exclusion.
if (FUZZ_GET_ATTR_INT(mutex, "held") != 0) { FUZZ_BAIL(); }
// Reinitialize the lock to the unlocked state.
mutex->reset();
// Reflect the unlocked state in attributes.
FUZZ_SET_ATTR_INT(mutex, "held", 0);
// Validation: lock should be considered unlocked after reset.
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(mutex, "held") == 0, "reset must leave lock unlocked");

// Non-recursive spinlock: calling lock while already held would deadlock.
if (FUZZ_GET_ATTR_INT(mutex, "held") != 0) { FUZZ_BAIL(); }
// Acquire the lock via busy-wait; single-threaded harness ensures quick acquisition.
mutex->lock();
FUZZ_SET_ATTR_INT(mutex, "held", 1);
// Optionally release immediately to diversify states and avoid over-locking.
unsigned int choose_release = *FUZZ_PARAM(unsigned int) & 1u;
if (choose_release) {
  mutex->unlock();
  FUZZ_SET_ATTR_INT(mutex, "held", 0);
}
// Validation: if we didn't release, the lock must be marked as held.
int held = FUZZ_GET_ATTR_INT(mutex, "held");
FUZZ_ASSERT(held == 0 || held == 1, "held attribute must be boolean");

int was_held = FUZZ_GET_ATTR_INT(mutex, "held");
bool acquired = mutex->try_lock();
if (was_held == 0) {
  // When unlocked, try_lock must succeed for this spinlock implementation.
  FUZZ_ASSERT(acquired, "try_lock must acquire when unlocked");
  FUZZ_SET_ATTR_INT(mutex, "held", 1);
  // Optionally release immediately to keep pool balanced.
  unsigned int choose_release = *FUZZ_PARAM(unsigned int) & 1u;
  if (choose_release) {
    mutex->unlock();
    FUZZ_SET_ATTR_INT(mutex, "held", 0);
  }
} else {
  // When already held, try_lock must not acquire.
  FUZZ_ASSERT(!acquired, "try_lock must fail when already held");
  // State remains held.
  FUZZ_SET_ATTR_INT(mutex, "held", 1);
}
// Validation: attribute matches actual intention post-call.
int held = FUZZ_GET_ATTR_INT(mutex, "held");
FUZZ_ASSERT(held == 0 || held == 1, "held attribute must be boolean");

// Must only unlock when currently held; otherwise violates API contract.
if (FUZZ_GET_ATTR_INT(mutex, "held") == 0) { FUZZ_BAIL(); }
mutex->unlock();
FUZZ_SET_ATTR_INT(mutex, "held", 0);
// Validation: state reflects unlocked after successful unlock.
FUZZ_ASSERT(FUZZ_GET_ATTR_INT(mutex, "held") == 0, "unlock must leave lock unlocked");

// Avoid concurrent reset/open/close by relying on single-threaded fuzz execution
