FUZZ_SET_ATTR_INT_GLOBAL("logger_locked", 0);
// Validation: reset should leave logger unopened; attributes cleared accordingly.

// Must have an active logger
if (FUZZ_GET_ATTR_INT_GLOBAL("logger_open") == 0) { FUZZ_BAIL(); }
// Avoid re-entrant locking as spinlock is not known to be re-entrant
if (FUZZ_GET_ATTR_INT_GLOBAL("logger_locked") != 0) { FUZZ_BAIL(); }

rubinius::logger::lock();
FUZZ_SET_ATTR_INT_GLOBAL("logger_locked", 1);
// Validation: one lock acquisition recorded; an unlock must follow in another stub.

